@Component("dispute-handler")
@ProcessingGroup("dispute-processing-group")
public class DisputeEventHandler {
	
	// core constructor
	DisputeEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateDisputeEvent
     */
    @EventHandler
    public void handle( CreateDisputeEvent event) {
        entityManager.persist(new Dispute(event.getDisputeId(), event.getDisputeReference(), event.getRaisedOn(), event.getReason(), event.getTransaction(), event.getCustomer(), event.getAccount(), event.getPaymentCard(), event.getStatus()));
    }

    /*
     * @param	event UpdateDisputeEvent
     */
    @EventHandler
    public Dispute handle( UpdateDisputeEvent event) {
    	entityManager.merge(new Dispute(event.getDisputeId(), event.getDisputeReference(), event.getRaisedOn(), event.getReason(), event.getTransaction(), event.getCustomer(), event.getAccount(), event.getPaymentCard(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteDisputeEvent
     */
    @EventHandler
    public void on( DeleteDisputeEvent event) {
    	Dispute entity = new Dispute();
   
    	// ------------------------------------------
    	// apply the DisputeId
    	// ------------------------------------------
    	entity.setDisputeId( event.getDisputeId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final DisputeRepository disputeEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(DisputeEventHandler.class.getName());

}
